import java.util.*;

public class Main {
    public static void main(String[] args) {
        long windowSizeMillis = 60000; // each window covers 1 minute of event time

        WindowedAggregator aggregator = new WindowedAggregator(windowSizeMillis);

        // Two genuine events for ad-1, both inside the window [0, 60000).
        aggregator.process(new ClickEvent("evt-1", "ad-1", 1000));
        aggregator.process(new ClickEvent("evt-2", "ad-1", 2000));

        // A duplicate delivery of evt-1, simulating an at-least-once retry.
        aggregator.process(new ClickEvent("evt-1", "ad-1", 1000));

        // One genuine event for a different ad, ad-2, same window.
        aggregator.process(new ClickEvent("evt-3", "ad-2", 1500));

