// One click event, carrying the identity needed for both deduplication and windowing.
class ClickEvent {
    String eventId;         // unique id, used to detect retried duplicates
    String adId;             // which ad this click belongs to
    long eventTimeMillis;     // when the click actually happened, not when it arrived

    ClickEvent(String eventId, String adId, long eventTimeMillis) {
        this.eventId = eventId;
        this.adId = adId;
        this.eventTimeMillis = eventTimeMillis;
    }
}

// Groups events into fixed-size event-time windows per ad, deduplicates by event
// id, and routes events that arrive after their window's watermark has passed
// into a separate late-event store instead of silently dropping them.
class WindowedAggregator {
    private final long windowSizeMillis;                                          // size of each aggregation window
    private final Set<String> seenEventIds = new HashSet<>();                        // every event id counted so far, for dedup
    private final Map<String, Map<Long, Integer>> countsByAdAndWindow = new HashMap<>(); // adId -> windowStart -> count
    private final List<ClickEvent> lateEvents = new ArrayList<>();                          // events that missed their window
    private long watermark = 0;                                                              // how far event time has progressed

    WindowedAggregator(long windowSizeMillis) {
        this.windowSizeMillis = windowSizeMillis;
    }

    // Returns true if this event was late (routed to the late store), false if it
    // was processed normally (either counted, or rejected as a duplicate).
    boolean process(ClickEvent event) {
        if (seenEventIds.contains(event.eventId)) {
            return false; // a duplicate, at-least-once retry; never counted twice
        }

        long windowStart = windowStartFor(event.eventTimeMillis); // which window this event's time falls into
        long windowEnd = windowStart + windowSizeMillis;

        if (windowEnd <= watermark) {
            // This event's window has already closed from the streaming layer's point of
            // view, so it is stored separately instead of silently being dropped.
            lateEvents.add(event);
            return true;
        }

        seenEventIds.add(event.eventId);                        // mark this event id as counted, guarding against future duplicates
        countsByAdAndWindow
            .computeIfAbsent(event.adId, id -> new HashMap<>())    // get or create this ad's window map
            .merge(windowStart, 1, Integer::sum);                     // increment this window's count by 1
        return false;
    }

    // Advances the watermark, closing any window that now ends at or before it.
    void advanceWatermark(long newWatermark) {
        this.watermark = newWatermark;
    }

    int getCount(String adId, long windowStart) {
        Map<Long, Integer> windows = countsByAdAndWindow.get(adId);
        if (windows == null) return 0;
        return windows.getOrDefault(windowStart, 0);
    }

    // Folds a previously-late event directly into its correct window's count,
    // called only by the reconciliation job, bypassing the watermark check since
    // reconciliation runs after all lateness has already been accounted for.
    void reconcileLateEvent(ClickEvent event) {
        if (seenEventIds.contains(event.eventId)) return; // still guard against double counting even during reconciliation
        seenEventIds.add(event.eventId);
        long windowStart = windowStartFor(event.eventTimeMillis);
        countsByAdAndWindow
            .computeIfAbsent(event.adId, id -> new HashMap<>())
            .merge(windowStart, 1, Integer::sum);
    }

    List<ClickEvent> drainLateEvents() {
        List<ClickEvent> drained = new ArrayList<>(lateEvents);
        lateEvents.clear();
        return drained;
    }

    private long windowStartFor(long eventTimeMillis) {
        return (eventTimeMillis / windowSizeMillis) * windowSizeMillis; // floor to the start of this event's window
    }
}

// Periodically reprocesses every stored late event, correcting the aggregator's
// counts so the final, exact figures used for billing include everything.
class ReconciliationJob {
    private final WindowedAggregator aggregator;

    ReconciliationJob(WindowedAggregator aggregator) {
        this.aggregator = aggregator;
    }

    void run() {
        for (ClickEvent lateEvent : aggregator.drainLateEvents()) {
            aggregator.reconcileLateEvent(lateEvent); // fold each late event into its correct window's exact count
        }
    }
}

