struct ClickEvent {
    std::string eventId;      // unique id, used to detect retried duplicates
    std::string adId;            // which ad this click belongs to
    long long eventTimeMillis;      // when the click actually happened, not when it arrived
};

// Groups events into fixed-size event-time windows per ad, deduplicates by event
// id, and routes events that arrive after their window's watermark has passed
// into a separate late-event store instead of silently dropping them.
class WindowedAggregator {
public:
    explicit WindowedAggregator(long long windowSizeMillis) : windowSizeMillis_(windowSizeMillis) {}

    // Returns true if this event was late (routed to the late store), false if it
    // was processed normally (either counted, or rejected as a duplicate).
    bool process(const ClickEvent& event) {
        if (seenEventIds_.count(event.eventId)) {
            return false;   // a duplicate, at-least-once retry; never counted twice
        }

        long long windowStart = windowStartFor(event.eventTimeMillis);   // which window this event's time falls into
        long long windowEnd = windowStart + windowSizeMillis_;

        if (windowEnd <= watermark_) {
            // This event's window has already closed from the streaming layer's point of
            // view, so it is stored separately instead of silently being dropped.
            lateEvents_.push_back(event);
            return true;
        }

        seenEventIds_.insert(event.eventId);   // mark this event id as counted, guarding against future duplicates
        countsByAdAndWindow_[event.adId][windowStart]++;   // increment this window's count by 1
        return false;
    }

    // Advances the watermark, closing any window that now ends at or before it.
    void advanceWatermark(long long newWatermark) { watermark_ = newWatermark; }

    int getCount(const std::string& adId, long long windowStart) {
        auto it = countsByAdAndWindow_.find(adId);
        if (it == countsByAdAndWindow_.end()) return 0;
        auto wit = it->second.find(windowStart);
        return wit == it->second.end() ? 0 : wit->second;
    }

    // Folds a previously-late event directly into its correct window's count,
    // called only by the reconciliation job, bypassing the watermark check since
    // reconciliation runs after all lateness has already been accounted for.
    void reconcileLateEvent(const ClickEvent& event) {
        if (seenEventIds_.count(event.eventId)) return;   // still guard against double counting even during reconciliation
        seenEventIds_.insert(event.eventId);
        long long windowStart = windowStartFor(event.eventTimeMillis);
        countsByAdAndWindow_[event.adId][windowStart]++;
    }

    std::vector<ClickEvent> drainLateEvents() {
        std::vector<ClickEvent> drained = lateEvents_;
        lateEvents_.clear();
        return drained;
    }

private:
    long long windowStartFor(long long eventTimeMillis) {
        return (eventTimeMillis / windowSizeMillis_) * windowSizeMillis_;   // floor to the start of this event's window
    }

    long long windowSizeMillis_;                                          // size of each aggregation window
    std::set<std::string> seenEventIds_;                                      // every event id counted so far, for dedup
    std::map<std::string, std::map<long long, int>> countsByAdAndWindow_;       // adId -> windowStart -> count
    std::vector<ClickEvent> lateEvents_;                                          // events that missed their window
    long long watermark_ = 0;                                                       // how far event time has progressed
};

// Periodically reprocesses every stored late event, correcting the aggregator's
// counts so the final, exact figures used for billing include everything.
class ReconciliationJob {
public:
    explicit ReconciliationJob(WindowedAggregator* aggregator) : aggregator_(aggregator) {}

    void run() {
        for (auto& lateEvent : aggregator_->drainLateEvents()) {
            aggregator_->reconcileLateEvent(lateEvent);   // fold each late event into its correct window's exact count
        }
    }

private:
    WindowedAggregator* aggregator_;
};

int main() {
    std::cout << std::boolalpha;
    long long windowSizeMillis = 60000;   // each window covers 1 minute of event time

    WindowedAggregator aggregator(windowSizeMillis);

    // Two genuine events for ad-1, both inside the window [0, 60000).
    aggregator.process({ "evt-1", "ad-1", 1000 });
    aggregator.process({ "evt-2", "ad-1", 2000 });

    // A duplicate delivery of evt-1, simulating an at-least-once retry.
    aggregator.process({ "evt-1", "ad-1", 1000 });

    // One genuine event for a different ad, ad-2, same window.
    aggregator.process({ "evt-3", "ad-2", 1500 });

    // Advance the watermark past this window's end, closing it for the streaming layer.
    aggregator.advanceWatermark(60000);

    std::cout << "Before reconciliation:\n";
    std::cout << "  ad-1 window [0,60000) count: " << aggregator.getCount("ad-1", 0) << "\n";
    std::cout << "  ad-2 window [0,60000) count: " << aggregator.getCount("ad-2", 0) << "\n";
    std::cout << "  duplicate evt-1 correctly not double counted: " << (aggregator.getCount("ad-1", 0) == 2) << "\n";

    // A late event for ad-1, event time 500, belongs to the already-closed window [0,60000).
    ClickEvent lateEvent{ "evt-4", "ad-1", 500 };
    bool wasLate = aggregator.process(lateEvent);
    std::cout << "Late event correctly routed to the late store instead of the live window: " << wasLate << "\n";
    std::cout << "  ad-1 window [0,60000) count still unchanged before reconciliation: " << aggregator.getCount("ad-1", 0) << "\n";

    // The batch reconciliation job picks up every stored late event and folds it in.
    ReconciliationJob reconciliation(&aggregator);
    reconciliation.run();

    std::cout << "After reconciliation:\n";
    std::cout << "  ad-1 window [0,60000) exact final count: " << aggregator.getCount("ad-1", 0) << "\n";
    std::cout << "  ad-2 window [0,60000) exact final count: " << aggregator.getCount("ad-2", 0) << "\n";
    return 0;
